        audit.recordOnCommit("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + request.user()
                + " name=" + person.getName() + " from=" + from);
        rollup.recordChanges(person.getSheetId(), request.user(), before);
    }
}

